/* This template illustrates how to add custom field for employee ID but in dialog display/lookup employee name instead
STEP 1 - Copy class and make mandatory changes:
This class can be used as template for custom code clases List of things to change for specific report: Mandatory changes : 1. Copy class, rename it to your prefered class name 2. Change LACReportName attribute to specify with which report name this class should work
STEP 2 - Add field variable and method but hide it in dialog: 1. Create variable that will store dialog field value (see example_EmployeeId in class declaration) 2. Create method that gets/sets this variable and add attributes for saving, but set visibility attribute to FALSE (see method parmExample_EmployeeId) 3. Create temporrary variable for employee dialog field. This variable will not be saved in last values, and will be used only in dialog (see example_EmployeeNameInDialog in class declaration) 4. Create method that gets/sets this temporrary variable and set visibility attribute to TRUE (see method parmExample_EmployeeNameInDialog)
STEP 3 - Create functionality for dialog fields interaction: 1. Overwrite method report_dialogPostRun, and use getDialogField() for custom added dialog fields, or getDialogFieldPredefined() - for dialog fields defined in LACReportParameters table
STEP 4 - Build report query and set range just before execution 1. Overwrite queryBuild method and initialize query 2. Overwrite report_runInit and set range for HCMWorker data source
see more info about methods that can be overwritten in parent class: LACValueSource_CustomCode */ [ DataContractAttribute, SysOperationContractProcessingAttribute(classstr(LACRunQueryUIBuilder)), LACValueSourceAttribute('CustomCode', 'Lasernet custom code'), // "CustomCode" is name shown in value expressions for this class // "Lasernet custom code" is description that is shown in value expressions for this class LACReportName(classStr(LACTutorialCustomCode_EmployeeLookupCode)) ] // Attribute indicating that this class should be used for LACTutorialCustomCode_EmployeeLookup report
class LACTutorialCustomCode_EmployeeLookupCode extends LACValueSource_CustomCode { HcmPersonnelNumberId example_EmployeeId; str example_EmployeeNameInDialog;
}

Method.Source:
//   ================================================  Step 2 ===========================================================================
/// <summary>
///     This method is used as example how to add Dialog field into report dialog. Method attributes indicates to builder to include it into dialog
/// </summary>
/// <param name = "_custRange">The value to set</param>
/// <returns>Example_CustRange value</returns>
[   DataMemberAttribute,                           // Save value in class, when switching server-client side, last value
    SysOperationControlVisibilityAttribute(false) ] // Hide in dialog
public HcmPersonnelNumberId parmExample_EmployeeId(HcmPersonnelNumberId _employeeId = example_EmployeeId)
{
    example_EmployeeId = _employeeId;
    return example_EmployeeId;
}

/// <summary>
///     This method is used as example how to add Dialog field into report dialog. Method attributes indicates to builder to include it into dialog
/// </summary>
/// <param name = "_custRange">The value to set</param>
/// <returns>Example_CustRange value</returns>
[   DataMemberAttribute,
    SysOperationControlVisibilityAttribute(true) ] // Show in dialog, but not data member attribute, because we are not saving name
public str parmExample_EmployeeNameInDialog(str _employeeNameInDialog = example_EmployeeNameInDialog)
{
    example_EmployeeNameInDialog = _employeeNameInDialog;
    return example_EmployeeNameInDialog;
}

//   ================================================  Step 3 ===========================================================================

/// <summary>
///    This method is called when all dialog form controls are created and dialog is ready to be shown to user
/// </summary>
public void report_dialogPostRun()
{
    DialogField         dialogField;
    FormStringControl   fsc;
    super();
    // Registering modified method for Example_CustGroupId
    dialogField = this.getDialogField(methodStr(LACTutorialCustomCode_EmployeeLookup, parmExample_EmployeeNameInDialog));
    dialogField.label('Employee');
    fsc = dialogField.fieldControl();
    fsc.OnModified += eventhandler(this.example_EmployeeName_onModified);
    fsc.OnLookup += eventhandler(this.example_EmployeeName_onLookup);
    fsc.displayHeight(1); // Single line
}

/// <summary>
///    Code that handles employee name field modifications
/// </summary>
/// <param name = "_formControl">Employee name control</param>
/// <param name = "e">Event args</param>
public void example_EmployeeName_onModified(FormControl _formControl, FormControlEventArgs e)
{
    HcmWorker           worker;
    DirPartyTable       dpt;
    FormStringControl   fsc = _formControl as FormStringControl;
    // ret = fsc.modified();
    worker = HcmWorker::findByPersonnelNumber(fsc.text());
    if (worker) // Check if employee id is entered
    {
        this.parmExample_EmployeeId(worker.PersonnelNumber); // Setting employee id
        fsc.text(worker.name());      // Replacing entered id with employee name
    }
    else // If employee name is entered
    {
        // compare with stored empoyeeId
        worker = HcmWorker::findByPersonnelNumber(this.parmExample_EmployeeId());
        if (worker && worker.name() == fsc.text())
        {
            return; // if the same - nothing has changed
        }
        else  // If different name than the one stored, attempt to find employee
        {
            dpt = DirPartyTable::findByName(fsc.text(), DirPartyType::Person);
            worker = HcmWorker::findByPerson(dpt.RecId);
            this.parmExample_EmployeeId(worker.PersonnelNumber);
            fsc.text(worker.name());
        }
    }
}

/// <summary>
///     Event handler for employee name lookup
/// </summary>
/// <param name="fsc">
///     Calling control
/// </param>
/// <param name="e">
///     Calling control
/// </param>
public void example_EmployeeName_onLookup(FormControl fsc, FormControlEventArgs e)
{
    HcmWorkerLookup workerLookup = HcmWorkerLookup::newActiveEmployees();
    FormControlCancelableSuperEventArgs cancelSuper = e as FormControlCancelableSuperEventArgs;
    cancelSuper.cancelSuperCall();
    workerLookup.lookupWorker(fsc as FormStringControl);

}

//   ================================================  Step 4 ===========================================================================

/// <summary>
/// This method serves as example how to build your own query from code. This method builds
/// not only query, but also guidlines for default XML document layout (by adding defaut fields, and Layout options on datasource)
/// </summary>
/// <returns></returns>
[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')] // value _DO_NOT_SHOW_ indicates framework, that this method is not 'value' method, and should
// be shown in lookups for value expressions
public Query queryBuild()
{
    Query                queryLocal = new Query();
    // At this example, we will build CustTable query
    // While building query, no parameters and related sources exist
    // specify ranges after report_runInit() is executed
    QueryBuildDataSource qbds;
    // add data source

    qbds = queryLocal.addDataSource(tableNum(HcmWorker));    // Add datasource
    qbds.name(tableStr(HcmWorker)); // Data source name will be used as report data source name, so to avoid names like CustTable_1, we set
    // name the same as table name.
    // add fields
    // It's mandatory to add fields with queryBuildAddField() because it serves as source for loading default report elements
    this.queryBuildAddField(qbds, fieldStr(HcmWorker, PersonnelNumber));
    // or method
    this.queryBuildAddMethod(qbds, tableMethodStr(HcmWorker, name));


    /*
    // Adding another datasource
    qbds2 = qbds.addDataSource(tableNum(MyTable2));
    qbds2.name(tableStr(MyTable2)); // Specify meaningfull name for data source
    qbds2.joinMode(JoinMode::InnerJoin);
    qbds2.fetchMode(QueryFetchMode::One2One);
    qbds2.relations(true);

    // and field
    this.queryBuildAddField(qbds2, fieldStr(MyTable2, NumberOf));

    // !!!! Do not forget this when adding more data sources:
    // Specifying layout property (both tables will be shown in the same xml path depth)
    this.queryBuildAddLayout(query, qbds2, LACQueryDSLayout::SameLevel);
    */
    return queryLocal;
}

/// <summary>
///     Setting query range for selected customers
/// </summary>
[LACValueSourceRestrictionAttribute('_DO_NOT_SHOW_', '')]
public void report_runInit()
{
    QueryBuildDataSource qbds;
    Query                queryLocal;

    super();

    queryLocal = this.getQueryRun().query(); // Retrieving Query from run query service
    qbds = queryLocal.dataSourceTable(tableNum(HcmWorker));
    SysQuery::findOrCreateRange(qbds, fieldNum(HcmWorker, PersonnelNumber)).value(this.parmExample_EmployeeId()); // Manually setting query range
}

/// <summary>
///   Constructor method, initializing instance of the class
/// </summary>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_EmployeeLookupCode construct()
{
    return new LACTutorialCustomCode_EmployeeLookupCode();
}

/// <summary>
///   Unpacks class instance. Required method, allowing to cache the custom code for the report execution
/// </summary>
/// <param name = "packedClass">Packed class instance</param>
/// <returns>Class instance</returns>
public static LACTutorialCustomCode_EmployeeLookupCode Create(container packedClass)
{
    LACTutorialCustomCode_EmployeeLookupCode valueSource = LACTutorialCustomCode_EmployeeLookupCode::construct();
    valueSource.unpack(packedClass);
    return valueSource;
}
